// ─── Painted Team Tower trees (art override) ────────────────────────────────
//
// The team trees from one small atlas (public/images/towers/, PAINTED_TOWERS —
// generated by tools/tower-sheets/pack.mjs from a text-only Gemini painting):
// a blue (player) and a red (enemy) tree — same green oak, the TEAM COLOUR is
// on its bow and pennant — in three damage states plus a felled stump:
//   hp > 60 %  healthy · hp > 25 %  damaged (bites, crack, plaster)
//   hp > 0     nearly destroyed (jagged trunk, dizzy) · hp 0  felled stump
//              on a scatter of leaves and splinters.
//
// Registration: the HEALTHY tree's silhouette is centred on the tower's
// collision centre and sized so its half width is TOWER_ART_HALF_W × the
// collision radius — the crown and trunk cover the hittable circle, and the
// part beyond the wall bulges out over the rim as before. Every other state
// is drawn at the same scale standing on the same ground point (the painted
// cell's centre x, its silhouette's bottom), so the tree loses its crown in
// place instead of jumping.
//
// Purely visual: it reads tower hp / flash, never writes anything.
// Procedural fallback (returns false — the caller draws its vector tree):
//  - until the atlas has loaded;
//  - when the sprite would be drawn ABOVE its own resolution (render-sharpness
//    rule — the device scale is read from the context transform);
//  - with `?art=procedural` (A/B), in jsdom / node.
import { PAINTED_TOWERS, type PaintedTowerName } from '@/use/paintedTowers'
import { prependBaseUrl } from '@/utils/function'

/** Healthy tree's painted half width over the tower collision radius. */
export const TOWER_ART_HALF_W = 1.2
/** Above this many device px per atlas px the procedural tree is drawn. */
const MAX_UPSCALE = 1.02

/** Largest css-px-per-arena-unit scale at which a tower of `radius` still
 *  draws its painted tree on a `dpr` display (MAX_UPSCALE) — the arena fit
 *  stops there instead of trading the painting for the vector fallback. */
export const towerArtMaxScale = (radius: number, dpr: number): number => {
  const meta = PAINTED_TOWERS
  if (!meta || radius <= 0) return Infinity
  const k = (radius * TOWER_ART_HALF_W) / meta.ref.halfW
  return (MAX_UPSCALE * 0.995) / (k * Math.max(1, dpr))
}

/** Damage state from the hp fraction: 0 healthy, 1 damaged, 2 nearly
 *  destroyed, 3 felled. */
export const towerDamageStage = (hp: number, maxHp: number): 0 | 1 | 2 | 3 => {
  if (hp <= 0) return 3
  const f = maxHp > 0 ? hp / maxHp : 1
  return f > 0.6 ? 0 : f > 0.25 ? 1 : 2
}

/** The painted stump is ~2.5x as wide as the tree's trunk: 1 / 2.5. */
export const FELLED_STUMP_SCALE = 0.4

const SPRITE_OF: Readonly<Record<'player' | 'npc', readonly PaintedTowerName[]>> = {
  player: ['blue0', 'blue1', 'blue2', 'blueFelled'],
  npc: ['red0', 'red1', 'red2', 'redFelled']
}

type Ctx = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D

let atlas: HTMLImageElement | null = null
let requested = false
let revision = 0
/** Bumps when the painted tower atlas lands — key the static bake on it. */
export const towerArtRevision = (): number => revision
// #Consistency-3: the lush green trees stood unchanged on ash / ice / ruin floors. Each theme
// grades the painted tree once (offscreen, cached per sprite) so it belongs to its ground; the
// team bows stay readable (blue vs red). No `ctx.filter` support (Safari) = untinted, as before.
const TREE_GRADE: Readonly<Record<string, string>> = {
  volcanic: 'saturate(0.5) brightness(0.78) sepia(0.3) contrast(1.05)',
  snowy: 'saturate(0.7) brightness(1.1) hue-rotate(16deg)',
  ruins: 'saturate(0.68) brightness(0.92)',
  rocky: 'saturate(0.82) brightness(0.93)'
}
let treeTheme = ''
/** Set the arena theme the trees are graded for (the static bake key already includes it). */
export const setTowerTheme = (theme: string): void => { treeTheme = theme }
const graded = new Map<string, HTMLCanvasElement | OffscreenCanvas>()
const gradedSprite = (name: PaintedTowerName): HTMLCanvasElement | OffscreenCanvas | null => {
  const grade = TREE_GRADE[treeTheme]
  if (!grade || name.endsWith('Felled') || !atlas) return null
  const key = `${name}|${treeTheme}`
  const hit = graded.get(key)
  if (hit) return hit
  const s = PAINTED_TOWERS?.sprites[name]
  if (!s) return null
  let c: HTMLCanvasElement | OffscreenCanvas
  if (typeof OffscreenCanvas !== 'undefined') c = new OffscreenCanvas(s.w, s.h)
  else { c = document.createElement('canvas'); c.width = s.w; c.height = s.h }
  const g = c.getContext('2d') as CanvasRenderingContext2D | null
  if (!g || !('filter' in g)) return null
  g.filter = grade
  g.drawImage(atlas, s.x, s.y, s.w, s.h, 0, 0, s.w, s.h)
  graded.set(key, c)
  return c
}

/** White silhouettes for the hit flash, baked lazily once per sprite. */
const flashSprites = new Map<PaintedTowerName, HTMLCanvasElement | OffscreenCanvas>()

const artAllowed = (): boolean => {
  if (typeof Image === 'undefined' || typeof location === 'undefined') return false
  if (typeof navigator !== 'undefined' && /jsdom/i.test(navigator.userAgent)) return false
  return !/[?&]art=procedural(?:&|$)/.test(location.search)
}

/** Start loading the tower atlas (no-op when absent / already asked). */
export const preloadTowerArt = (): void => {
  if (requested || !PAINTED_TOWERS || !artAllowed()) return
  requested = true
  const img = new Image()
  img.decoding = 'async'
  img.onload = () => {
    atlas = img
    revision++
  }
  img.src = prependBaseUrl(`images/towers/${PAINTED_TOWERS.file}?v=${PAINTED_TOWERS.v}`)
}

const flashSprite = (name: PaintedTowerName): HTMLCanvasElement | OffscreenCanvas | null => {
  const hit = flashSprites.get(name)
  if (hit) return hit
  const s = PAINTED_TOWERS?.sprites[name]
  if (!s || !atlas) return null
  let c: HTMLCanvasElement | OffscreenCanvas
  if (typeof OffscreenCanvas !== 'undefined') c = new OffscreenCanvas(s.w, s.h)
  else {
    c = document.createElement('canvas')
    c.width = s.w
    c.height = s.h
  }
  const g = c.getContext('2d') as CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D | null
  if (!g) return null
  g.drawImage(atlas, s.x, s.y, s.w, s.h, 0, 0, s.w, s.h)
  g.globalCompositeOperation = 'source-in'
  g.fillStyle = '#ffffff'
  g.fillRect(0, 0, s.w, s.h)
  flashSprites.set(name, c)
  return c
}

/**
 * Draw the painted tree of a tower centred on (x, y) (caller is in arena
 * units — the static bake, or the per-frame redraw during a hit flash).
 * `flash` 0..1 lays the tree's white silhouette over it. Returns false when
 * the caller should draw its procedural tree instead.
 */
export const drawPaintedTower = (
  ctx: Ctx,
  side: 'player' | 'npc', x: number, y: number, radius: number,
  hp: number, maxHp: number, flash = 0
): boolean => {
  const meta = PAINTED_TOWERS
  if (!meta) return false
  preloadTowerArt()
  if (!atlas) return false
  const k = (radius * TOWER_ART_HALF_W) / meta.ref.halfW
  const t = ctx.getTransform()
  const deviceScale = Math.hypot(t.a, t.b) || 1
  if (k * deviceScale > MAX_UPSCALE) return false
  const stage = towerDamageStage(hp, maxHp)
  const name = SPRITE_OF[side][stage]!
  const s = meta.sprites[name]
  // Ground point: where the healthy tree's silhouette centre lands on (x, y).
  const gx = x - meta.ref.dx * k
  const gy = y - meta.ref.dy * k
  // Flat contact shadow (no blur, no gradient).
  ctx.fillStyle = 'rgba(28, 18, 8, 0.24)'
  ctx.beginPath()
  ctx.ellipse(gx + radius * 0.06, gy - radius * 0.06, radius * (stage === 3 ? 0.78 : 0.92), radius * 0.3, 0, 0, Math.PI * 2)
  ctx.fill()
  if (stage === 3) {
    const dbr = meta.sprites.debris
    ctx.drawImage(atlas, dbr.x, dbr.y, dbr.w, dbr.h, gx - dbr.gx * k, gy - dbr.gy * k + radius * 0.12, dbr.w * k, dbr.h * k)
  }
  // #Consistency-2: the painted felled stump is ~2.5x the healthy tree's trunk; draw it
  // at FELLED_STUMP_SCALE of the tree's scale, still standing on the same ground point.
  const ks = stage === 3 ? k * FELLED_STUMP_SCALE : k
  const dx = gx - s.gx * ks
  const dy = gy - s.gy * ks
  const tinted = gradedSprite(name)
  if (tinted) ctx.drawImage(tinted as CanvasImageSource, dx, dy, s.w * ks, s.h * ks)
  else ctx.drawImage(atlas, s.x, s.y, s.w, s.h, dx, dy, s.w * ks, s.h * ks)
  if (flash > 0.05) {
    const f = flashSprite(name)
    if (f) {
      const prev = ctx.globalAlpha
      ctx.globalAlpha = prev * flash * 0.55
      ctx.drawImage(f as CanvasImageSource, dx, dy, s.w * ks, s.h * ks)
      ctx.globalAlpha = prev
    }
  }
  return true
}
